command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="ce51aa2804902990776071293990dad48a4ed1f1"
$candidate="384ae72d69d1f55ceb98cf3595cb62478f418418"
$branch="work/search-content-regex-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "content regex release fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before content regex release validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "content regex candidate moved before release validation"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-content-regex-release-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "content regex release worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "content regex release diff check failed"}

  & cmd /c tests\winui\m19\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "content regex M19 Release build failed"}
  $env:FLY_M19_CONFIG="Release"
  & python -X utf8 tests\winui\m19\test_native.py
  if($LASTEXITCODE -ne 0){throw "content regex M19 Release native failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "content regex canonical Release build failed"}

  & python -X utf8 tools\winui\run_checks.py gui --area search --configuration Release
  if($LASTEXITCODE -ne 0){throw "content regex focused Search GUI failed"}

  $shot=Join-Path $temp "logs\phase6-winui\m19-focused-real-gui.png"
  if(-not (Test-Path -LiteralPath $shot -PathType Leaf)){throw "content regex AFTER screenshot missing"}
  $evidence=Join-Path $repo "logs\remote-evidence"
  New-Item -ItemType Directory -Force -Path $evidence | Out-Null
  Copy-Item -LiteralPath $shot -Destination (Join-Path $evidence "search-content-regex-after.png") -Force
  $guiLog=Get-ChildItem -LiteralPath (Join-Path $temp "logs\winui-scoped") -Filter "*gui-search-Release.log" |
      Sort-Object LastWriteTime -Descending | Select-Object -First 1
  if($guiLog){Copy-Item -LiteralPath $guiLog.FullName -Destination (Join-Path $evidence "search-content-regex-gui.log") -Force}

  Write-Host "CONTENT_REGEX_M19_RELEASE=PASS"
  Write-Host "CONTENT_REGEX_RELEASE_BUILD=PASS"
  Write-Host "CONTENT_REGEX_GUI=PASS"
  Write-Host "CONTENT_REGEX_AFTER_SCREENSHOT=PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
